package dev.kelmagic.server;
import dev.kelmagic.*;import dev.kelmagic.research.Research;import net.minecraft.server.level.ServerPlayer;import net.minecraft.core.BlockPos;import net.minecraft.world.level.block.*;import net.minecraft.world.level.ClipContext;import net.minecraft.world.phys.*;
public final class MagicTransformation {
 public static boolean cast(ServerPlayer p){var override=dev.kelmagic.artifact.ArtifactMagic.aim(p);if(override!=null)return override.type()==HitResult.Type.BLOCK&&dev.kelmagic.artifact.ArtifactWorld.allowed(p,override.block().getBlockPos())&&transform(p,override.block().getBlockPos());var eye=p.getEyePosition();var hit=p.serverLevel().clip(new ClipContext(eye,eye.add(p.getLookAngle().scale(Config.RANGE.get())),ClipContext.Block.OUTLINE,ClipContext.Fluid.NONE,p));return hit.getType()==HitResult.Type.BLOCK&&transform(p,hit.getBlockPos());}
 public static boolean transform(ServerPlayer p,BlockPos pos){var old=p.serverLevel().getBlockState(pos);
  net.minecraft.world.level.block.state.properties.BooleanProperty tint=old.is(dev.kelmagic.content.MagicGrove.GLASS.get())?dev.kelmagic.content.ConnectedGlassBlock.VIOLET:old.is(MagicStudy.TABLE.get())?dev.kelmagic.archive.ArchiveTableBlock.VIOLET:null;
  if(tint!=null){if(!recolor(p,pos,old,tint))return false;if(old.is(MagicStudy.TABLE.get()))MagicProgress.award(p,"word_born_power");p.serverLevel().sendParticles(net.minecraft.core.particles.ParticleTypes.END_ROD,pos.getX()+.5,pos.getY()+.7,pos.getZ()+.5,10,.2,.2,.2,.02);return true;}
  boolean torch=old.is(Blocks.TORCH)||old.is(Blocks.WALL_TORCH)||old.is(Blocks.REDSTONE_TORCH)||old.is(Blocks.REDSTONE_WALL_TORCH)||old.is(Blocks.SOUL_TORCH)||old.is(Blocks.SOUL_WALL_TORCH);boolean lantern=java.util.Set.of(Blocks.OCHRE_FROGLIGHT,Blocks.PEARLESCENT_FROGLIGHT,Blocks.VERDANT_FROGLIGHT,Blocks.SHROOMLIGHT,Blocks.REDSTONE_LAMP,Blocks.SEA_LANTERN,Blocks.GLOWSTONE).contains(old.getBlock());if(!torch&&!lantern)return false;var next=lantern?MagicLamps.DURABLE_LANTERN.get().defaultBlockState():old.hasProperty(WallTorchBlock.FACING)?MagicLamps.DURABLE_WALL.get().defaultBlockState().setValue(WallTorchBlock.FACING,old.getValue(WallTorchBlock.FACING)):MagicLamps.DURABLE_TORCH.get().defaultBlockState();if(!WorldSpells.place(p,pos,next,true))return false;Research.observe(p,torch?"transform:torch":"transform:lantern");p.serverLevel().sendParticles(net.minecraft.core.particles.ParticleTypes.END_ROD,pos.getX()+.5,pos.getY()+.5,pos.getZ()+.5,12,.2,.2,.2,.02);return true;}
 /** Narrow, same-block appearance update; unlike general replacement it may retain the archivist table entity. */
 private static boolean recolor(ServerPlayer p,BlockPos pos,net.minecraft.world.level.block.state.BlockState old,net.minecraft.world.level.block.state.properties.BooleanProperty tint){
  var l=p.serverLevel();if(p.isSpectator()||!p.getAbilities().mayBuild||!l.hasChunkAt(pos)||!l.isInWorldBounds(pos)||!l.getWorldBorder().isWithinBounds(pos)||!l.mayInteract(p,pos)||!p.mayUseItemAt(pos,net.minecraft.core.Direction.UP,p.getMainHandItem()))return false;
  if(old.is(MagicStudy.TABLE.get())&&!(l.getBlockEntity(pos) instanceof dev.kelmagic.archive.ArchiveTableEntity))return false;
  var snapshot=net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,pos);if(!l.setBlock(pos,old.cycle(tint),3))return false;
  if(net.neoforged.neoforge.event.EventHooks.onBlockPlace(p,snapshot,net.minecraft.core.Direction.UP)){snapshot.restore();return false;}return true;
 }
 private MagicTransformation(){}
}
